This delay doesn't work properly on Windows when the interval is less than a millisecond. It always gets rounded to 1 ms and Windows' bad timer resolution can also cause it to jump higher than intended.

```cpp
	if (!is_flushing && setting_max_ops_per_second > 0) {
		const uint64_t min_interval_usec = 1000000 / setting_max_ops_per_second;
		if (min_interval_usec > 0) {
			uint64_t current_ticks = OS::get_singleton()->get_ticks_usec();
			if (current_ticks < next_io_op_ticks) {
				uint64_t delay_time = ((next_io_op_ticks - current_ticks) / 1000) * 1000;
				if (delay_time > 0) {
					OS::get_singleton()->delay_usec(delay_time);
				}
				while (OS::get_singleton()->get_ticks_usec() < next_io_op_ticks) {
					Thread::yield();
				}
			} else {
				next_io_op_ticks = current_ticks;
			}
			next_io_op_ticks += min_interval_usec;
