Dictionary AnimationMixer::get_animation_libraries() const {
	Dictionary ret;
	for (const AnimationLibraryData &lib : animation_libraries) {
		Dictionary d;
		List<StringName> ls;
		lib.library->get_animation_list(&ls);
		for (const StringName &an : ls) {
			d[an] = lib.library->get_animation(an);
		}
		ret[lib.name] = d;
	}
	return ret;
}
#endif // TOOLS_ENABLED
