  section_name_style = EditorPropertyNameProcessor::STYLE_CAPITALIZED;
}

// Only process group label if this is not the group or subgroup.
if ((i == 0 && component == group) || (i == 1 && component == subgroup)) {
  if (section_name_style == EditorPropertyNameProcessor::STYLE_LOCALIZED) {
    label = EditorPropertyNameProcessor::get_singleton()->translate_group_name(component);
    tooltip = component;
  } else {
    label = component;
    tooltip = EditorPropertyNameProcessor::get_singleton()->translate_group_name(component);
  }
  } else {
    label = EditorPropertyNameProcessor::get_singleton()->process_name(component, section_name_style, p.name, doc_name);
    tooltip = EditorPropertyNameProcessor::get_singleton()->process_name(component, EditorPropertyNameProcessor::get_tooltip_style(section_name_style), p.name, doc_name);
}
```

It processes all groups and subgroup labels, with exception if they are written by the developer, for example in GDScript on export_group() and export_subgroup().

GDScript:
<img width="278" height="215" alt="image" src="https://github.com/user-attachments/assets/7bbb3c6b-a6c9-4f6c-b73e-53eea90caef2" />

Before, the capitalize() on the `material.cpp` made the shader groups and subgroups get capitalized without following the `EditorPropertyNameProcessor::get_singleton()->process_name()`, but now if I take the capitalization out, the groups and sub-groups actually follow the GSCript convention of the labels staying the exact same as the developer wrote them:
<img width="273" height="242" alt="image" src="https://github.com/user-attachments/assets/83e65160-ea39-4a5a-87cb-ea17b4998b36" />


I actually think this is better than doing the process_name for shader groups and subgroups, as it is more consistent on the UI and it will not be necessary to have the Editor reference on `material.cpp`. What do you think?

